<script>
import BaseComponent from '@primevue/core/basecomponent';
import LabelStyle from 'primevue/label/style';

export default {
    name: 'BaseLabel',
    extends: BaseComponent,
    props: {
        as: {
            type: [String, Object],
            default: 'LABEL'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: LabelStyle,
    provide() {
        return {
            $pcLabel: this,
            $parentInstance: this
        };
    }
};
</script>
